	let o = wert;
	if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) { return null; } }
	if (!o || typeof o !== 'object') return null;
	const team = String(o.team_id || '').trim();
	const kanal = String(o.channel_id || '').trim();
	const id = String(o.id || '').trim();
	if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(team) || !/^19:[^\s]+@thread\.[a-z0-9]+$/i.test(kanal) || !/^\d{6,20}$/.test(id)) return null;
	return { team_id: team, channel_id: kanal, id };
}

function zeitText(iso, zeitzone) {
	const d = new Date(iso);
	if (!iso || Number.isNaN(d.getTime())) return '';
	try { return d.toLocaleString('de-DE', { timeZone: zeitzone || 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }); } catch (e) { return d.toISOString(); }
}

/** Freigabe-Karte ohne Buttons und ohne Link-Adressen (zum Speichern). Gibt null zurück, wenn ein Link übrig bliebe. */
function karteOhneLink(karte) {
	if (!karte || typeof karte !== 'object' || !Array.isArray(karte.body)) return null;
	// $schema ist nur die Schema-Adresse von Adaptive Cards (kein Link für Menschen) und wird nicht gespeichert.
	const { actions, selectAction, $schema, ...rest } = karte;
	const k = JSON.parse(JSON.stringify(rest));
	const weg = (o) => {
		if (Array.isArray(o)) return o.forEach(weg);
		if (o && typeof o === 'object') {
			delete o.selectAction; delete o.actions;
			for (const v of Object.values(o)) weg(v);
		}
	};
	weg(k);
	return /https?:\/\/|epa-freigabe\?t=/i.test(JSON.stringify(k)) ? null : k;
}

/**
 * Warten-Karte aus der ursprünglichen Freigabe-Karte (Spalte teams_karte): alle Angaben (vorhanden, fehlt noch,
 * Hinweise) bleiben, der Kopf zeigt "Wartet auf Antwort", der Entwurf wird durch den verschickten Text ersetzt,
 * Link-Hinweis und Button entfallen. Gibt null zurück, wenn die Karte nicht lesbar ist.
 */
function karteWarten(original, f, { kopf, zeilen }) {
	let k = original;
	if (typeof k === 'string') { try { k = JSON.parse(k); } catch (e) { return null; } }
	if (!k || !Array.isArray(k.body) || !k.body.length) return null;
	const tb = (text, extra) => ({ type: 'TextBlock', text, wrap: true, ...(extra || {}) });
	const body = [];
	for (const b of k.body.slice(1)) {
		if (b && b.type === 'TextBlock' && b.isSubtle && /Link|Es wird nichts ohne Klick/.test(String(b.text || ''))) continue;
		if (b && b.type === 'TextBlock' && /Erneut zur Freigabe/.test(String(b.text || ''))) continue;
		if (b && b.type === 'Container' && Array.isArray(b.items) && /ENTWURF DER/.test(String((b.items[0] || {}).text || ''))) {
			body.push({ ...b, items: [tb('VERSCHICKTE ' + (f.art === 'erinnerung' ? 'ERINNERUNG' : 'RÜCKFRAGE'), { weight: 'Bolder', size: 'Small', isSubtle: true }), tb(String(f.entwurf_text || (b.items[1] || {}).text || '').slice(0, 800))] });
			continue;
		}
		body.push(b);
	}
	const head = { type: 'ColumnSet', columns: [
		{ type: 'Column', width: 'stretch', items: [tb(kopf, { weight: 'Bolder', size: 'Medium' })] },
		{ type: 'Column', width: 'auto', items: [tb('WARTET', { weight: 'Bolder', size: 'Small', color: 'Accent' })] },
	] };
	const info = { type: 'Container', style: 'accent', spacing: 'Medium', items: zeilen.filter(Boolean).map((t) => tb(t, { spacing: 'Small' })) };
	return { type: 'AdaptiveCard', $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', version: '1.4', body: [head, ...body.slice(0, 1), info, ...body.slice(1)] };
}

/**
 * Karte, die eine Freigabe-Karte im Kanal nach der Entscheidung ersetzt (ohne Link).
 * zustand: Status der Freigabe (gesendet, abgelehnt, fehler, ersetzt, unzustellbar) oder "erneuert" (neuer Link verschickt).
 * Gibt null zurück, wenn die Karte (noch) nicht geändert werden soll (offen, in_versand, unbekannt).
 */
function karteZustand(fg, { zustand, zeitzone, jetzt, frist, original } = {}) {
	const f = fg || {};
	const z = String(zustand || f.status || '');
	const wer = String(f.entscheider || '').trim();
	let titel; let stil; let zeilen = [];
	if (z === 'gesendet') {
		// Karte im Kanal "Warten auf Kunde": Rückfrage ist raus, Antwort steht aus.
		const manuell = f.entscheidung === 'manuell_gesendet';
		const was0 = f.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage';
		titel = '⏳ Wartet auf Antwort des Kunden';
		stil = 'accent';
		let gefragt = [];
		try { gefragt = (typeof f.fehlende_felder === 'string' ? JSON.parse(f.fehlende_felder || '[]') : (f.fehlende_felder || [])).map((x) => x.anzeigename || x.feldname).filter(Boolean); } catch (e) { gefragt = []; }
		zeilen = [
			was0 + (manuell ? ' direkt in Outlook verschickt' : f.bearbeitet ? ' bearbeitet und verschickt' : ' verschickt') + (manuell || !wer ? '' : ' von ' + wer) + ' · ' + zeitText(f.gesendet_am || jetzt, zeitzone),
			gefragt.length ? 'Gefragt: ' + gefragt.join(', ').slice(0, 300) : '',
			frist ? 'Antwort erwartet bis ' + zeitText(frist, zeitzone) : '',
		];
	} else if (z === 'abgelehnt') {
		titel = '❌ Abgelehnt'; stil = 'attention';
		zeilen = [(wer ? 'Von ' + wer + ' · ' : '') + zeitText(jetzt, zeitzone), f.grund ? 'Grund: ' + String(f.grund).slice(0, 300) : '', 'Der Vorgang liegt jetzt bei einem Mitarbeiter (Eskaliert / Manuell).'];
	} else if (z === 'fehler') {
		titel = '⚠️ Versand fehlgeschlagen'; stil = 'warning';
		zeilen = [(wer ? 'Freigegeben von ' + wer + ' · ' : '') + zeitText(jetzt, zeitzone), 'Die Mail wurde nicht gesendet. Nach Behebung kommt sie automatisch mit neuem Link erneut zur Freigabe.'];
	} else if (z === 'ersetzt') {
		titel = '↩️ Nicht mehr nötig'; stil = 'emphasis';
		zeilen = ['Der Kunde hat geantwortet, bevor die Rückfrage freigegeben wurde. Die Antwort wird verarbeitet.', zeitText(jetzt, zeitzone)];
	} else if (z === 'erneuert') {
		// Gilt für Erinnerung (alter Link noch gültig) und Erneuerung (alter Link gesperrt): immer die neue Karte nehmen.
		titel = '⏰ Ersetzt durch eine neue Karte'; stil = 'warning';
		zeilen = ['Für diesen Vorgang steht weiter unten im Kanal eine neue Karte mit neuem Freigabe-Link. Bitte nur die neue Karte verwenden.', zeitText(jetzt, zeitzone)];
	} else if (z === 'unzustellbar') {
		titel = '📭 Gesendet, aber nicht zugestellt'; stil = 'attention';
		zeilen = ['Die Mail kam beim Kunden nicht an. Siehe Meldung im Kanal „Bitte ansehen“.', zeitText(jetzt, zeitzone)];
	} else {
		return null;
	}
	const was = f.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage' + (Number(f.runde) > 0 ? ' (Runde ' + Number(f.runde) + ')' : '');
	const fakten = [{ title: 'Vorgang', value: String(f.vorgangs_id || '–') }, { title: 'Art', value: was }];
	if (f.betreff) fakten.push({ title: 'Betreff', value: String(f.betreff).slice(0, 150) });
	const tb = (text, extra) => ({ type: 'TextBlock', text, wrap: true, ...(extra || {}) });
	const karte = {
		type: 'AdaptiveCard', $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', version: '1.4',
		body: [
			{ type: 'Container', style: stil, bleed: true, items: [tb(titel, { weight: 'bolder', size: 'medium' })] },
			{ type: 'FactSet', facts: fakten, spacing: 'Medium' },
			...zeilen.filter(Boolean).map((t) => tb(t, { spacing: 'Small', isSubtle: true })),
		],
	};
	// Warten: möglichst die vollständige Freigabe-Karte mit allen Angaben übernehmen.
	const voll = z === 'gesendet' && original ? karteWarten(original, f, { kopf: titel, zeilen }) : null;
	const ziel = voll || karte;
	const marker = Buffer.from(JSON.stringify(ziel), 'utf8').toString('base64');
	const html = `<b>${esc(titel)}</b><br>Vorgang ${esc(f.vorgangs_id || '')}<br>${zeilen.filter(Boolean).map(esc).join('<br>')}<!--EPA_KARTE:${marker}-->`;
	// Verschickt: Die Karte verschwindet aus "Rückfragen" und kommt in "Warten auf Kunde" (Anlass rueckfrage_verschickt).
	return { titel, karte: ziel, html, verschieben: z === 'gesendet' };
}

/**
 * Kurzmeldung für "Systemmeldungen", wenn eine Rückfrage verschickt wurde: Absender und wichtigste Daten.
 * v = Vorgang (absender_name, absender_adresse, betreff, vorgangs_id).
 */
function meldungVerschickt(f, v, { zeitzone, jetzt, frist } = {}) {
	const vg = v || {};
	let gefragt = [];
	try { gefragt = (typeof f.fehlende_felder === 'string' ? JSON.parse(f.fehlende_felder || '[]') : (f.fehlende_felder || [])).map((x) => x.anzeigename || x.feldname).filter(Boolean); } catch (e) { gefragt = []; }
	const was = f.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage';
	const titel = '✅ ' + was + ' verschickt';
	const absender = [vg.absender_name, vg.absender_adresse ? '<' + vg.absender_adresse + '>' : ''].filter(Boolean).join(' ');
	const manuell = f.entscheidung === 'manuell_gesendet';
	const fakten = [
		{ title: 'Absender', value: absender || '–' },
		{ title: 'Betreff', value: String(vg.betreff || f.betreff || '–').slice(0, 150) },
		{ title: 'Vorgang', value: String(f.vorgangs_id || vg.vorgangs_id || '–') + (Number(f.runde) > 0 ? ' · Runde ' + Number(f.runde) : '') },
		{ title: 'Gefragt', value: gefragt.length ? gefragt.join(', ').slice(0, 200) : '–' },
		{ title: 'Verschickt', value: (manuell ? 'direkt in Outlook' : (f.entscheider ? 'von ' + f.entscheider : '')) + ' · ' + zeitText(f.gesendet_am || jetzt, zeitzone) },
	];
	if (frist) fakten.push({ title: 'Antwort bis', value: zeitText(frist, zeitzone) });
	const karte = { type: 'AdaptiveCard', $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', version: '1.4', body: [
		{ type: 'TextBlock', text: titel, weight: 'Bolder', size: 'Medium', color: 'Good', wrap: true },
		{ type: 'FactSet', facts: fakten, spacing: 'Small' },
		{ type: 'TextBlock', text: 'Die Karte steht jetzt in „3 Warten auf Kunde“, bis der Kunde antwortet.', isSubtle: true, size: 'Small', wrap: true, spacing: 'Small' },
	] };
	const html = `<b>${esc(titel)}</b><br>${fakten.map((x) => esc(x.title) + ': ' + esc(x.value)).join('<br>')}<!--EPA_KARTE:${Buffer.from(JSON.stringify(karte), 'utf8').toString('base64')}-->`;
	return { titel, karte, html };
}

/**
 * Weitere Freigabe-Karten desselben Vorgangs im Kanal (Doppelte, alte Karten), die beim Verschicken mit weg sollen.
 * nachrichten: [{ id, geloescht, text }] aus der Postfach-Aktion teams_kanal_lesen.
 */
function weitereKarten(nachrichten, vorgangsId, ausnahmen) {
	const vid = String(vorgangsId || '');
	if (!/^V-\d{4}-\d{4,}$/.test(vid)) return [];
	const aus = new Set((ausnahmen || []).map(String));
	return (nachrichten || []).filter((m) => m && m.id && !m.geloescht && !aus.has(String(m.id))
		&& String(m.text || '').includes('(' + vid + ')') && /Freigabe erforderlich/.test(String(m.text || ''))).map((m) => String(m.id));
}

/**
 * Was mit der Karte einer Freigabe passiert (EPA SW Freigabe-Karte).
 * - Karte in "Rückfragen", Freigabe verschickt: verschieben (neue Karte in "Warten auf Kunde", alte entfernen,
 *   dazu ältere Warten-Karten desselben Vorgangs entfernen, z. B. nach einer Erinnerung).
 * - Karte in "Warten", Zustand nicht mehr "gesendet" (Kunde hat geantwortet, nicht zugestellt, keine Reaktion): entfernen.
 * - Sonst Karte an Ort und Stelle ersetzen (abgelehnt, ersetzt, Link erneuert, Versand fehlgeschlagen).
 * @returns {{ aktion: 'verschieben'|'entfernen'|'aendern'|'nichts', grund?: string, html?: string, karte_ort?: object, ziel_channel_id?: string, entfernen?: object[] }}
 */
function kartenPlan({ fg, andere, zustand, wartenKanal, teamsNachricht, zeitzone, jetzt, frist }) {
	const f = fg || {};
	const tn = teamsNachrichtLesen(teamsNachricht || f.teams_nachricht);
	if (!f.freigabe_id) return { aktion: 'nichts', grund: 'Freigabe nicht gefunden' };
	if (!tn) return { aktion: 'nichts', grund: 'keine Teams-Karte gespeichert' };
	const z = String(zustand || f.status || '');
	const warten = /^19:[^\s]+@thread\.[a-z0-9]+$/i.test(String(wartenKanal || '')) ? String(wartenKanal) : '';
	const inWarten = Boolean(warten) && tn.channel_id === warten;
	if (inWarten) {
		if (z === 'gesendet') return { aktion: 'nichts', grund: 'Karte steht schon in "Warten auf Kunde"' };
		return { aktion: 'entfernen', karte_ort: tn, entfernen: [tn] };
	}
	const k = karteZustand(f, { zustand: z, zeitzone, jetzt, frist, original: f.teams_karte });
	if (!k) return { aktion: 'nichts', grund: 'Zustand ' + (z || '-') + ' ändert die Karte nicht' };
	if (k.verschieben && warten) {
		const alte = (andere || [])
			.filter((a) => a && a.freigabe_id && a.freigabe_id !== f.freigabe_id)
			.map((a) => teamsNachrichtLesen(a.teams_nachricht))
			.filter((t) => t && t.channel_id === warten);
		return { aktion: 'verschieben', html: k.html, karte_ort: tn, ziel_channel_id: warten, entfernen: [tn, ...alte] };
	}
	return { aktion: 'aendern', html: k.html, karte_ort: tn };
}

